import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand


class CertCrlFetch(GenericEMSSIMCommand):
    """Certcrlfetch command class."""

    def __init__(self, connection, delay=None, prompt=None, newline_chars=None, runner=None):
        """
        Certcrlfetch command.

        :param connection: moler connection to device, terminal when command is executed.
        :param delay: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(CertCrlFetch, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.delay = delay
        self.start_parsing = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "cert_crl_fetch"
        if self.delay:
            cmd = f"{cmd} -delay {str(self.delay)}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_line_start_parsing(line)
                self._parse_line_start_parsing_parameters(line)
                self._parse_line_parameters(line)
                self._parse_line_configuration_line(line)
                self._parse_line_end_parsing(line)
            except ParsingDone:
                pass
        return super(CertCrlFetch, self).on_new_line(line, is_full_line)

    _re_start_parsing = re.compile(r"-{10,}", re.I)

    def _parse_line_start_parsing(self, line):
        if not self.start_parsing and self._regex_helper.search_compiled(CertCrlFetch._re_start_parsing, line):
            self.start_parsing = True
            raise ParsingDone

    _re_start_parsing_parameters = re.compile(r"\|Parameters:", re.I)

    def _parse_line_start_parsing_parameters(self, line):
        if self.start_parsing and self._regex_helper.search_compiled(CertCrlFetch._re_start_parsing_parameters, line):
            self.current_ret["Parameters"] = {}
            raise ParsingDone

    _re_parameters = re.compile(r"\|\s+(?P<PARAM>.*)\s=>\s(?P<VALUE>.*)", re.I)

    def _parse_line_parameters(self, line):
        if self.start_parsing and self._regex_helper.search_compiled(CertCrlFetch._re_parameters, line):
            parameter = self._regex_helper.group("PARAM")
            value = self._regex_helper.group("VALUE")
            self.current_ret["Parameters"][parameter] = value
            raise ParsingDone

    _re_configuration_line = re.compile(r"\|(?P<ATTR>.*):(\s+(?P<VALUE>.*))*", re.I)

    def _parse_line_configuration_line(self, line):
        if self.start_parsing and self._regex_helper.search_compiled(CertCrlFetch._re_configuration_line, line):
            self.current_ret[self._regex_helper.group("ATTR")] = self._regex_helper.group("VALUE")
            raise ParsingDone

    def _parse_line_end_parsing(self, line):
        if self.start_parsing and self._regex_helper.search_compiled(CertCrlFetch._re_start_parsing, line):
            self.set_result(self.current_ret)
            raise ParsingDone


